#!/usr/bin/env python3
"""Freeze and reserve spot long-only BTC/ETH ratio mean-reversion rotation candidates."""
import hashlib,json,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];ROUND=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
source=ROOT/'research/experiments/20261012T035429Z/report.json';src=json.loads(source.read_text());filters=src['plan']['execution']['filters']
prior_path=ROOT/'research/experiments/20261012T035429Z/prior_evidence_audit.json';prior=json.loads(prior_path.read_text());assert len(prior['initial16_actual_results_checked'])==16 and all(x['evidence'] for x in prior['initial16_actual_results_checked'])
files={}
for a in ('BTC','ETH'):
 files[a]=[]
 for suffix in ('20240916T000000Z_20250916T000000Z_transfer_20261001','20250916T000000Z_20260916T000000Z_archive_20260929'):
  p=ROOT/f'data/normalized/binance/{a}/binance_{a}_{suffix}/spot_bars.parquet';files[a].append({'path':str(p.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size})
common={'literature':{'citation':'Mallik, S. (2021). Pricing cryptocurrencies: Modelling the ETHBTC spot-quotient variation as a diffusion process. arXiv:2111.11609.','url':'https://arxiv.org/abs/2111.11609','accessed_utc':'2026-10-12','use':'The paper reports mean reversion in intraday deviations between Binance ETHBTC and ETHUSDT/BTCUSDT quotient series. This daily log-price-ratio rotation is a simpler long-only adaptation, not a replication; ratio mean reversion in this two-year reused sample is not assumed.'},
 'data':{'source':'Binance spot 1m OHLCV, normalized closed bars','assets':files,'history_utc':'2024-09-16T00:00:00Z/2026-09-16T00:00:00Z','reuse_disclosure':'This period has been repeatedly used for strategy development and validation; it is not an untouched final holdout.'},
 'walk_forward':{'window_type':'rolling','train_days':365,'train_bars':365,'test_days':30,'test_bars':30,'step_days':30,'embargo_days':3,'embargo_bars':3,'folds':12,'continuous_oos':True,'first_test_index':368,'end_exclusive_index':728,'first_oos_execution_utc':'2025-09-19T00:01:00Z','terminal_execution_utc':'2026-09-14T00:01:00Z','parameter_fit':'None; all parameters frozen before evaluation. Daily ratio and trailing reference moments use only completed closes. No OOS position is replayed from warm-up history; portfolio state carries continuously over all adjacent test folds.'},
 'execution':{'filters_source':'research/experiments/20261012T035429Z/report.json','filters_source_sha256':sha(source),'filters_by_symbol':filters,'reference_price':'Next UTC day 00:01 one-minute open, after the previous daily candle close is available. Switches liquidate the current coin before buying the other at the same timestamp; both legs are costed. Historic L2 quotes are unavailable, so half-spread and impact are estimates, not fill guarantees.'},
 'costs':{'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'impact_coefficient':0.5,'impact_formula':'0.5 * sample std(previous 20 complete UTC daily log returns) * sqrt(order budget / mean quote turnover(previous 20 complete UTC days))','max_lagged_ADV_participation':0.001,'scenarios':[1,2,3],'spread_counted_once':True,'funding_borrow':'Not applicable; long-only spot.'},
 'prior_evidence':{'initial16_audit':str(prior_path.relative_to(ROOT)),'initial16_audit_sha256':sha(prior_path),'finding':'All 16 initial registry rows have actual backtest/report evidence; no exact missing-result starting configuration to rerun.'}}
plan={'round':ROUND.name,'frozen_at_utc':'2026-10-12T13:59:04Z','direction':'Long-only spot rotation from the BTC/ETH relative-price-ratio z-score','hypothesis':'Large deviations in log(BTC/ETH) from their trailing mean may partially revert; buying the relatively lagging asset and exiting as the ratio normalizes could diversify momentum approaches. Crypto relative relationships may be non-stationary, so sensitivity across lookback and entry threshold is mandatory.', 'grid':{'lookback_days':[20,40,60],'entry_zscore_threshold':[1.0,1.5,2.0],'fixed_exit_abs_zscore':0.5,'initial_capital_usdt_per_config':2000,'universe':['BTC','ETH']},'sensitivity_axes':['lookback_days','entry_zscore_threshold'],'rule':'For each completed UTC daily decision j=i-1, calculate x_j=ln(close_BTC[j]/close_ETH[j]). Calculate reference mean and sample standard deviation from the prior L completed ratio observations x[j-L:j] (current x_j excluded). z_j=(x_j-reference_mean)/reference_std; if std is zero, set z=0. If flat and z>entry_threshold, target ETH (BTC relatively rich); if z<-entry_threshold, target BTC (ETH relatively rich); otherwise stay cash. If holding ETH, remain while z>0.5, exit to cash when z<=0.5, and switch to BTC when z<-entry_threshold. If holding BTC, remain while z<-0.5, exit to cash when z>=-0.5, and switch to ETH when z>entry_threshold. Entry tests take precedence over exit-to-cash at opposite extremes; values at the entry boundary do not enter, and values at the exit boundary exit. Trade only when target changes. Execute after the daily signal at next UTC day 00:01 one-minute open. A switch sells first, then buys with remaining cash at the same recorded timestamp. Failed sells preserve the current holding and suppress the new buy; failed buys remain cash and are reconsidered next daily decision. No shorting, leverage, simultaneous positions, interest, cross-account transfer, timed exit, or pre-OOS fills.', 'allocation':'Each parameter configuration is a separate $2,000 USDT unlevered spot account. At most 100% is held in one coin; otherwise the account is in USDT. This is a state-dependent long-only allocation, not a fixed BTC/ETH weight portfolio.', 'failure_gates':{'all_cost_scenarios_positive':True,'minimum_positive_1x_folds':7,'maximum_3x_sampled_minute_close_drawdown_pct':25,'minimum_3x_neighborhood_positive_fraction':0.60,'minimum_1x_round_trips':2,'minimum_1x_gross_reference_pnl_to_cost':2.5,'no_cash_or_units_violations':True,'terminal_flat':True,'interpretation':'Passing means this repeated-history screen only; it does not establish an independent holdout or stable live profits.'},**common}
(ROUND/'spec.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
rows=[]
for look in (20,40,60):
 for threshold in (1.0,1.5,2.0):
  name=f'ratioMR_L{look}_Z{int(threshold*10):02d}'
  spec={'kind':'strategy','family':'spot-ratio-zscore-mean-reversion-rotation','market':'spot','timeframe':'1d','universe':['BTC/USDT','ETH/USDT'],'name':name,
   'logic':{'ratio':'x_j=ln(completed_close_BTC[j]/completed_close_ETH[j]). At signal j use sample mean/std of the prior L completed x values x[j-L:j]; exclude current x_j. z=(x_j-mean)/sample_std; if std==0 use 0.', 'entry':'When in cash, z>entry_zscore_threshold targets ETH (BTC relatively rich); z<-entry_zscore_threshold targets BTC (ETH relatively rich); else remain in cash. Boundaries are strict.', 'exit_and_switch':'While holding ETH, hold if z>0.5; exit to cash when z<=0.5; directly switch to BTC if z<-entry threshold. While holding BTC, hold if z<-0.5; exit when z>=-0.5; directly switch to ETH if z>entry threshold. Extreme opposite entry has priority. Trade only on target changes.', 'timing':'Use only completed UTC daily closes. Execute at next UTC day 00:01 one-minute open; a switch sells then buys at that same timestamp and charges both legs.', 'sizing':'Independent $2,000 long-only spot account, at most one coin held at a time or cash. No shorting, leverage, yield, transfer, or pre-OOS holding.'},
   'parameters':{'lookback_days':look,'entry_zscore_threshold':threshold,'exit_abs_zscore':0.5,'initial_capital_usdt':2000,'walk_forward_train_days':365,'walk_forward_test_days':30,'walk_forward_step_days':30,'embargo_days':3,'folds':12,'oos_first_test_index':368,'oos_end_exclusive_index':728,'cost_multipliers':[1,2,3]}}
  p=ROUND/'specs'/f'{name}.json';p.write_text(json.dumps(spec,indent=2)+'\n');rows.append({'name':name,'spec':str(p.relative_to(ROOT)),'fingerprint':registry.fingerprint(spec),'is_comparator':False})
for a in ('BTC','ETH'):
 name=f'hold_360d_{a}';spec={'kind':'strategy','family':'spot-ratio-mean-reversion-hold-reference','market':'spot','timeframe':'1d','universe':[a+'/USDT'],'name':name,'logic':{'entry':'Buy at first OOS UTC day 00:01 execution independent of ratio signal.','exit':'Hold to shared terminal execution and liquidate with costs.','sizing':'Independent $2,000 unlevered long-only benchmark; no cash yield.'},'parameters':{'initial_capital_usdt':2000,'oos_first_test_index':368,'oos_end_exclusive_index':728,'cost_multipliers':[1,2,3]}}
 p=ROUND/'specs'/f'{name}.json';p.write_text(json.dumps(spec,indent=2)+'\n');rows.append({'name':name,'spec':str(p.relative_to(ROOT)),'fingerprint':registry.fingerprint(spec),'is_comparator':True})
(ROUND/'batch.json').write_text(json.dumps(rows,indent=2)+'\n')
with (ROUND/'reserve.log').open('w') as log:
 for row in rows:
  cp=subprocess.run([sys.executable,str(ROOT/'research/automation/registry.py'),'reserve',str(ROOT/row['spec'])],cwd=ROOT,text=True,capture_output=True)
  log.write(json.dumps({'name':row['name'],'returncode':cp.returncode,'stdout':cp.stdout.strip(),'stderr':cp.stderr.strip()},ensure_ascii=False)+'\n');log.flush()
  if cp.returncode:raise SystemExit(f"reserve failed for {row['name']}: {cp.returncode} {cp.stderr}")
print(f'reserved {len(rows)} unique definitions before evaluation')
